#ifndef __aarch64__
#error Expected an AArch64 compiler
#endif
#ifdef __x86_64__
#error Unexpected x86 compiler macros
#endif
__bf16 add(__bf16 a,__bf16 b){return a+b;}
float to_float(__bf16 a){return (float)a;}
__bf16 from_float(float a){return (__bf16)a;}
_Float16 half(__bf16 a){return (_Float16)a;}
__bf16 brain(_Float16 a){return (__bf16)a;}
_Static_assert(sizeof(__bf16)==2,"size");
_Static_assert(_Generic(((__bf16)1+(__bf16)2),__bf16:1,default:0),"arithmetic");
